var tb=function(k){return live===false?HOLE_UN[k]:HOLE[k]&&HOLE[k][kind];};
var k=A.featPick(null,h,{kind:'hole',pick:pick,peek:true,keys:function(x){var l=tb(x);return!!(l&&l.length);}});
