ev.forEach(function(e){(e.t&&e.t.length?e.t:['-']).forEach(function(k){(g[k]=g[k]||[]).push(e);});});
(c.ties||[]).forEach(function(t){if(g[t[0]])rows.push({h:t[1],l:g[t[0]]});});
