if(s.tables&&s.tables.length)h+='<div class="gearsec"><h3>このほかに選ばれる場面</h3><ul class="tipul">'+s.tables.map(function(t){return'<li>'+esc(t.n)+'：'+t.c+(t.p?' 組':' 種類')+'</li>';}).join('')+'</ul></div>';
